import{_ as i,H as t,f as l,i as a}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"10 | 技术管理者如何获得下属的认同？","description":"","frontmatter":{},"headers":[{"level":2,"title":"拉近距离：给团队赋能","slug":"拉近距离-给团队赋能","link":"#拉近距离-给团队赋能","children":[]},{"level":2,"title":"助其成长：转变思维","slug":"助其成长-转变思维","link":"#助其成长-转变思维","children":[]},{"level":2,"title":"激发潜能：满足需求","slug":"激发潜能-满足需求","link":"#激发潜能-满足需求","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"技术领导力实战笔记2022/10｜技术管理者如何获得下属的认同？.md","filePath":"技术领导力实战笔记2022/10｜技术管理者如何获得下属的认同？.md","lastUpdated":1795558086000}'),p={name:"技术领导力实战笔记2022/10｜技术管理者如何获得下属的认同？.md"};function n(s,e,E,r,o,h){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="_10-技术管理者如何获得下属的认同" tabindex="-1">10 | 技术管理者如何获得下属的认同？ <a class="header-anchor" href="#_10-技术管理者如何获得下属的认同" aria-label="Permalink to &quot;10 | 技术管理者如何获得下属的认同？&quot;">​</a></h1><p>你好，我是童军，目前是华锐技术资管营销研发团队总监。今天我将从自己的工作场景出发，讲讲我是如何和团队小伙伴相处沟通，并获得认同的。</p><p>我们先看一个小故事。</p><ul><li>我刚当上主管那会儿，在和新入职同事沟通具体工作时，经常发生争执。当时我是这样做的：新同事入职后，我给 TA 下达工作任务，并定好时间计划。在 Review 工作产出时，我尽心尽责地把存在的问题都一一提了出来，但新同事却因此产生了逆反心理。我说一句，新同事反驳一句，甚至还会刻意选择我不擅长的领域，反问我具体的解决方案，对抗情绪蔓延开来。</li></ul><p>为什么会出现这种情况呢？我们来分析一下。</p><ul><li><p>首先，我刚刚上任，我们之间并不熟悉，同事对我的技术能力存疑。这时候提出意见很难获得同事的认同，相反他还会去挑战你，试探你。</p></li><li><p>其次，我在沟通时，容易表现出“你怎么能犯这种低级错误”的表情，而并不关心同事看到后的感受，错误的沟通方式也是矛盾爆发的一个关键因素。</p></li></ul><p>同事工作习惯不好，思维方式不对，我们确实应该及时提出帮助他成长。但如果我们在没有获得认同的情况下，一直提出要求或批评，不仅达不到帮助其成长的效果，反而会导致工作安排变得越来越困难。因此，开展管理工作的前提是获得下属的认同。那具体如何获得他们的认同呢？</p><p>这里我把我多年管理技术团队的经验总结成了三个关键点，分享给你。</p><h2 id="拉近距离-给团队赋能" tabindex="-1">拉近距离：给团队赋能 <a class="header-anchor" href="#拉近距离-给团队赋能" aria-label="Permalink to &quot;拉近距离：给团队赋能&quot;">​</a></h2><p>开发人员对技术能力较强的领导有一种天然的亲近感，因为同质相惜，我们总是愿意和同类待在一起，而且很多人都有慕强心理，你足够强大的时候，很多人都会不自觉地向你靠拢。所以，你需要在团队中呈现你的专业能力，并给团队赋能，从而获得认可。</p><p>在这里我们要远离一个误区，并不是说技术领导者需要对所有技术样样精通，才能体现出专业能力。如果你只是前端或者后端出身，怎样呈现出技术专业能力呢？</p><p>大道相通，无论是哪一端，用哪门语言开发，都可以囊括至以下几点。</p><ol><li><p>基础知识：语言基础、计算机原理、数据结构与算法、网络知识、设计模式等。</p></li><li><p>功能开发：开发框架、类库等。</p></li><li><p>非功能性开发：可靠性、安全、性能、兼容性等。</p></li><li><p>协同：开发、集成、测试、部署运维等。</p></li></ol><p>你不妨先从上面内容中找出跨端、跨语言通用的能力，比如基础知识中的计算机原理、数据结构与算法、网络知识、设计模式；非功能性开发中的安全；协同中的 DevOps 思想、代码管理。然后结合团队目前有待加强的地方，挑选出合适的点给团队赋能。赋能的方式可以是相关的培训、具体的落地实践，也可以是在技术方案或代码评审中帮团队把关。</p><p>我在做管理的不同阶段是这样做的。</p><p>阶段一：从移动端 TL 到管理整个前端，我发现 Web 端的工程化思想比较薄弱，仍是纯手工拷贝文件发布版本的模式，不仅效能低下且容易出错。我结合 Gitlab Hooks 及 Jenkins 写好脚本，把 Web 端做到每日自动构建部署，Web 端的小伙伴真切感受到了什么叫做程序员要越懒越好。</p><p>阶段二：从管理前端到负责整个研发团队，彼时后端仍是采用 SVN 管理代码，我给大家培训了 GitLab Flow 的工作流程规范，并改用 Git 管理代码。后端的核心工程师之一在年度总结中认为这是年度最有价值的提升。</p><p>通过考察团队的实际情况，找出短板，然后通过培训等方式给团队赋能，解决团队中的实际问题，不仅可以展现出自己的技术实力获得同事的信任和认可，还能提升团队的能力和效率。</p><h2 id="助其成长-转变思维" tabindex="-1">助其成长：转变思维 <a class="header-anchor" href="#助其成长-转变思维" aria-label="Permalink to &quot;助其成长：转变思维&quot;">​</a></h2><p>运用你的技术实力给团队赋能，补齐团队的短板是第一步，但除了拓展团队的知识面、提升团队的能力之外，我们还需要关注团队的思维方式。因为正确的思维方式能够让他们迅速成长，少走很多弯路。</p><p>比如我团队内部非常倡导先思而后行，有些开发人员会在需求一知半解，技术方案都没想清楚时就开始写代码，殊不知返工是效率最大的天敌。我们可以看一下一开始就动手和想好再动手对项目风险的影响。先战而后求胜比先胜而后求战的风险要大得多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/1.png" alt=""></a></p><ul><li>图片来自华锐技术</li></ul><p>以下是我们团队执行的研发流程，在详细设计评审完成前，是禁止开发代码的，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/2.png" alt=""></a></p><ul><li>图片来自华锐技术</li></ul><p>我们在管理团队的时候，要格外关注这一点，让团队成员养成这样的开发习惯，从整体上提高开发效率，减少无用功，把时间用在“刀刃”上。</p><p>除了培养员工先思而后行的思维方式，我们还要从传统的任务导向转向目标导向，我们先看下任务型和目标型团队的区别。</p><p>任务导向型团队</p><ul><li><p>像火车，一环扣一环，每个岗位只看到“上游”传递过来的任务。</p></li><li><p>通常由上游推动下游行动，车头提供动力，其他车厢只提供阻力。</p></li><li><p>每个岗位都以完成自己的任务为首要目标（有可能忽视、抵触团队整体目标）。</p></li></ul><p>目标导向型团队</p><ul><li><p>像火箭，所有人都清晰地知悉共同目标，直接对业务目标负责。</p></li><li><p>所有决策都以是否有利于业务目标为唯一标准。</p></li><li><p>所有岗位都是推动引擎，提供推力而非阻力。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/3.png" alt=""></a></p><ul><li>图片来自华锐技术</li></ul><p>对技术团队而言，如何做到目标导向，对齐业务目标呢？</p><ul><li><p>首先，要提出业务目标：给产品经理提供正确的需求故事模版，每次需求评审时先说清楚：谁，在什么场景使用，产生什么价值。其实这个环节很容易做成产品经理讲一遍需求，技术觉得实现没问题就通过了的会议形式，而忽略了真正重要的事情是评审需求合理性。</p></li><li><p>其次，完善与修订目标：团队成员共同参与业务模型设计、需求反讲等重要环节；开发人员在开发、测试人员在测试过程中不断地对需求的合理性提出挑战。</p></li></ul><p>最终，让业务目标变成所有人共同参与讨论，逐渐丰富与完善的过程，而不是一个层层传递信息衰减的过程。</p><p>俗话说，授人以鱼不如授人以渔，先思而后行和目标导向这两种思维方式，能够提升成员的工作效率，使其快速成长起来，从整体上看，团队的力量更加集中，也能获得更好的结果。</p><h2 id="激发潜能-满足需求" tabindex="-1">激发潜能：满足需求 <a class="header-anchor" href="#激发潜能-满足需求" aria-label="Permalink to &quot;激发潜能：满足需求&quot;">​</a></h2><p>解决完能力和思维的问题，最后还剩下一个非常关键的点——意愿，让团队成员从“能干”变成“想干”。现代管理学之父德鲁克认为，管理的本质是激发善意。如果能激发出小伙伴的善意与潜能，相信你得到的不仅是认可，团队效能还可以再上一个台阶。</p><p>那么，如何激发小伙伴的善意与潜能呢？我们可以使用马斯洛的需求理论来分析一下。</p><p>马斯洛把人类需求分为生理需求、安全需求、社交需求、尊重需求和自我实现需求五个等级，我们可以根据小伙伴们不同的需要给予对应激励、照应，从而获得他们内心深处真正的认同，比如：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/10/4.png" alt=""></a></p><p>对你来说，可能这些都是一些小细节，但对团队成员有很大影响。如果你能够站在他们的角度去思考问题，主动帮他们解决一些后顾之忧，那你收获的就不单单是成员的认可了，而是一支充满力量的队伍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>千人同心，则得千人之力；万人异心，则无一人之用。——出自《淮南子·兵略训》</li></ul><p>打造一支团结有力量的队伍，就需要上下齐心。所以今天我根据自己过往的经验给你分享了三个获得下属认同的途径，我们来回顾一下。</p><ul><li><p>呈现你的专业技术能力，通过给团队赋能，不仅拉近了距离，也获得了认可。</p></li><li><p>改变团队成员的思维方式，培养先思而后行和目标导向思维，提升每个成员的效率和责任感，帮助他们快速成长起来。</p></li><li><p>根据他们的需要给予不同的激励，激发意愿和潜力，获得他们内心深处的认同。</p></li></ul><p>最后，希望你在管理之路上能得到更多认同者，陪你征战四方，所向披靡。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>今天的内容就讲到这里，留下一道思考题给你。如果你团队中有人因为失恋而萎靡不振，你会怎么处理？欢迎你把答案写到留言区，和我一起讨论。</p>',51)])])}const c=i(p,[["render",n]]);export{u as __pageData,c as default};
